    document.addEventListener('DOMContentLoaded', function() {
      const btn = document.getElementById('apply-draft-btn');
      const draftEl = document.getElementById('extracted-draft-data');
      if (!btn || !draftEl) return;

      const draft = JSON.parse(draftEl.textContent);

      btn.addEventListener('click', function() {
        // Map draft fields to Django admin form input IDs (id_<fieldname>)
        const fieldMap = {
          title: 'id_title',
          description: 'id_description',
          external_url: 'id_external_url',
          price_min_cents: 'id_price_min_cents',
          price_max_cents: 'id_price_max_cents',
          is_free: 'id_is_free',
        };
        Object.entries(fieldMap).forEach(function([draftKey, inputId]) {
          const el = document.getElementById(inputId);
          if (el && draft[draftKey] !== undefined && draft[draftKey] !== null) {
            if (el.type === 'checkbox') {
              el.checked = draft[draftKey];
            } else {
              el.value = draft[draftKey];
            }
          }
        });
        // Handle datetime fields -- Django admin uses SplitDateTimeWidget (two inputs):
        // id_start_0 = date portion (YYYY-MM-DD), id_start_1 = time portion (HH:MM)
        if (draft.start) {
          const [datePart, timePart] = draft.start.split('T');
          const startDate = document.getElementById('id_start_0');
          const startTime = document.getElementById('id_start_1');
          if (startDate) startDate.value = datePart;
          if (startTime) startTime.value = timePart ? timePart.substring(0, 5) : '';
        }
        if (draft.end) {
          const [datePart, timePart] = draft.end.split('T');
          const endDate = document.getElementById('id_end_0');
          const endTime = document.getElementById('id_end_1');
          if (endDate) endDate.value = datePart;
          if (endTime) endTime.value = timePart ? timePart.substring(0, 5) : '';
        }
      });

      // Keyboard shortcuts (only when not focused on a form input)
      document.addEventListener('keydown', function(e) {
        if (['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName)) return;
        const statusSelect = document.getElementById('id_status');
        const saveBtn = document.querySelector('[name="_save"]');
        if (e.key === 'a' || e.key === 'A') {
          if (statusSelect) statusSelect.value = 'published';
          if (saveBtn) saveBtn.click();
        } else if (e.key === 'r' || e.key === 'R') {
          if (statusSelect) statusSelect.value = 'rejected';
          if (saveBtn) saveBtn.click();
        }
        // J/K next/prev navigation requires server-side cursor -- deferred to future bead
      });
    });

## Admin tests (/workspace/events/tests/test_admin.py)

Full test file content. Note: the _event_post_data helper provides all required Django admin
form fields including inline management form fields (required to avoid "ManagementForm data
is missing" errors on POST):

    from django.test import TestCase
    from django.contrib.auth import get_user_model
    from django.utils import timezone
    from datetime import timedelta, datetime

    from events.models import Event, Tag
    from ingestion.models import RawMessage, ExtractionAttempt
    from organizers.models import Organizer

    User = get_user_model()


    class EventAdminTest(TestCase):
        def setUp(self):
            self.superuser = User.objects.create_superuser(
                email='admin@example.com', password='password'
            )
            self.client.force_login(self.superuser)
            self.organizer = Organizer.objects.create(name='Test Org', slug='test-org-admin')

        def _make_event(self, status='draft', **kwargs):
            defaults = dict(
                title='Test Event',
                slug='test-event-admin',
                organizer=self.organizer,
                start=timezone.now() + timedelta(days=1),
                status=status,
            )
            defaults.update(kwargs)
            return Event.objects.create(**defaults)

        def _event_post_data(self, event, status='published'):
            return {
                'title': event.title,
                'slug': event.slug,
                'status': status,
                'start_0': event.start.strftime('%Y-%m-%d'),
                'start_1': event.start.strftime('%H:%M:%S'),
                'currency': event.currency,
                'eventimage_set-TOTAL_FORMS': '0',
                'eventimage_set-INITIAL_FORMS': '0',
                'eventimage_set-MIN_NUM_FORMS': '0',
                'eventimage_set-MAX_NUM_FORMS': '1000',
                '_save': 'Save',
            }

        def test_event_changelist_defaults_to_draft_filter(self):
            draft_event = self._make_event(status='draft')
            published_event = self._make_event(
                status='published', slug='pub-event-admin'
            )
            response = self.client.get('/admin/events/event/')
            self.assertEqual(response.status_code, 200)
            # Draft event should be in results; published should not
            self.assertContains(response, draft_event.title)
            self.assertNotContains(response, published_event.title)

        def test_change_form_includes_extraction_data(self):
            raw = RawMessage.objects.create(
                source_type='telegram_bot_forward', raw_payload={}, sender_id='123'
            )
            event = self._make_event(raw_message=raw)
            ExtractionAttempt.objects.create(
                raw_message=raw,
                event=event,
                model_name='claude-opus-4-7',
                prompt_version='v1',
                raw_response={'title': 'Test'},
                extracted_draft={'title': 'Test', 'confidence': 0.9},
                confidence_score=0.9,
                success=True,
            )
            response = self.client.get(f'/admin/events/event/{event.id}/change/')
            self.assertEqual(response.status_code, 200)
            self.assertIn(b'extracted-draft-data', response.content)

        def test_consent_captured_on_first_publish(self):
            self.organizer.consent_recorded_at = None
            self.organizer.save()
            event = self._make_event(status='draft')
            post_data = self._event_post_data(event, status='published')
            post_data['organizer'] = self.organizer.pk
            response = self.client.post(
                f'/admin/events/event/{event.id}/change/',
                data=post_data,
                follow=True,
            )
            self.organizer.refresh_from_db()
            self.assertIsNotNone(self.organizer.consent_recorded_at)
            self.assertEqual(self.organizer.consent_method, 'telegram_forward_implied')

        def test_consent_not_overwritten_on_second_publish(self):
            original_time = timezone.now() - timedelta(days=10)
            self.organizer.consent_recorded_at = original_time
            self.organizer.consent_method = 'explicit_opt_in'
            self.organizer.save()
            event = self._make_event(status='draft')
            post_data = self._event_post_data(event, status='published')
            post_data['organizer'] = self.organizer.pk
            self.client.post(
                f'/admin/events/event/{event.id}/change/',
                data=post_data,
                follow=True,
            )
            self.organizer.refresh_from_db()
            # consent_recorded_at should not have changed (already set)
            self.assertEqual(
                self.organizer.consent_recorded_at.date(),
                original_time.date()
            )
            self.assertEqual(self.organizer.consent_method, 'explicit_opt_in')

